# -*- coding: utf-8 -*-
# Макарычев 7: сверка с ответами учебника (стр. 248–253 скана, перенесены вручную: mak7_answers.txt) + проверка ключа по собственному условию. 26.09
P = {}
SRC = "Макарычев 7 (ответы учебника по скану + OCR условий) + пересчёт, 26.09"
def E(t, why, **kw): P[t] = dict(why=why, src=SRC, **kw)
E("G7_TB_39_1022.2", "ключ неверен: (x² − 10x + 6)(2x + b) = 2x³ + (b − 20)x² + (12 − 10b)x + 6b; равенство коэффициентов при x³ и x: 2 = 12 − 10b ⇒ b = 1 (совпадает с ответом учебника; было −0,8)",
  k=r"$b = 1$", dadd=[(r"$b = -0{,}8$", "прежний неверный ключ")])
E("G7_TB_43_1086.4", "ключ был округлён (x = −1,35, y = −3,2): из y = 2x − 0,5 и 3x − 5y = 12 получаем x = −19/14, y = −45/14. Условие совпадает с учебником; ответ учебника (−1,5; −3,5) удовлетворяет 3x − 5y = 13 — опечатка в ответах",
  k=r"$x = -1\dfrac{5}{14}$, $y = -3\dfrac{3}{14}$")
E("G7_TB_32_834.4", "ключ был десятичным приближением 3,4166666667: 3y − 6,25 = 4 ⇒ y = 41/12 = 3 5/12; неверные варианты тоже были десятичными приближениями — записаны точно",
  k=r"$y = 3\dfrac{5}{12}$", dval={1: r"$y = 2\dfrac{1}{12}$", 2: r"$y = 1\dfrac{11}{12}$"})
E("G7_TB_35_907.1", "в ключе стояла переменная x, а уравнение записано относительно m", k=r"$m = \pm 5$")
QG = "в условие попали лишние пункты упражнения, а ключ дан только к одному; условие оставлено для того пункта, к которому дан ключ (сверено с OCR учебника)"
E("G7_TB_1_5.1", QG + " — № 5 а)", q=r"Представьте в виде бесконечной десятичной дроби число $\dfrac{1}{3}$.", k=r"$0,(3)$",
  dval={0: r"$0{,}3$", 1: r"$0,(33)$", 2: r"$1,3$"})
E("G7_TB_1_5.5", QG + " — № 5 з)", q=r"Представьте в виде бесконечной десятичной дроби число $\dfrac{3}{16}$.")
E("G7_TB_18_389.3", QG + " — № 389 ж)", q=r"Найдите значение степени $\left(-\dfrac{1}{2}\right)^{5}$.")
E("G7_TB_18_389.5", "в условии осталась оторванная метка пункта «к)»; условие приведено к двум пунктам, к которым дан ключ", q=r"Найдите значения степеней: $\left(-\dfrac{1}{2}\right)^{6}$ и $-2{,}4^{2}$.")
E("G7_TB_8_148.5", QG + " — № 148 з)", q=r"Решите уравнение $1\dfrac{1}{3}x+4=\dfrac{1}{3}x+1$.")
E("G7_TB_35_906.5", "в условие попали два пункта (з) и и)), а ключ был только к первому, хотя неверные варианты описывали оба; ключ дополнен: 81x² + 4 = 0 корней не имеет",
  q=r"Решите уравнения: $25x^{2}-16=0$ и $81x^{2}+4=0$.", k=r"$x = \pm 0{,}8$; уравнение $81x^{2}+4=0$ корней не имеет")
E("G7_TB_22_490.1", "в условии «a^{2b}» вместо a²b (ключ −8a⁶b³ соответствует (−2a²b)³)", qrep=(r"(-2a^{2b})^{3}", r"(-2a^{2}b)^{3}"))
